<?php
defined('BASEPATH') OR exit('No direct script access allowed');
class Booking_discounts extends MY_Controller {
    public function __construct(){parent::__construct();$this->load->model('Booking_discounts_model');}
    public function index(){$data['discounts']=$this->Booking_discounts_model->getAll();$data['title']='booking_discounts';$this->load->view('templates/top',$data);$this->load->view('pos/booking_discounts/list',$data);$this->load->view('templates/bottom');}
    public function add(){$data['title']='booking_discounts';$this->load->view('templates/top',$data);$this->load->view('pos/booking_discounts/add',$data);$this->load->view('templates/bottom');}
    public function do_add(){if($this->input->method(true)!=='POST')show_error('Invalid request method',405);$name=trim((string)$this->input->post('name',true));$percent=(int)$this->input->post('percent');if($name===''||$percent<1||$percent>100){$this->session->set_flashdata('error','Enter a name and a percentage from 1 to 100.');redirect('pos/booking_discounts/add');return;}$id=$this->Booking_discounts_model->add($name,$percent);$this->session->set_flashdata($id?'success':'error',$id?'Booking discount saved.':'Unable to save booking discount.');redirect('pos/booking_discounts');}
    public function edit($id){$discount=$this->Booking_discounts_model->get($id);if(!$discount)show_404();$data=array('discount'=>$discount,'title'=>'booking_discounts');$this->load->view('templates/top',$data);$this->load->view('pos/booking_discounts/edit',$data);$this->load->view('templates/bottom');}
    public function do_edit($id){if($this->input->method(true)!=='POST')show_error('Invalid request method',405);$discount=$this->Booking_discounts_model->get($id);if(!$discount)show_404();$name=trim((string)$this->input->post('name',true));$percent=(int)$this->input->post('percent');if($name===''||$percent<1||$percent>100){$this->session->set_flashdata('error','Enter a name and a percentage from 1 to 100.');redirect('pos/booking_discounts/edit/'.$id);return;}$this->Booking_discounts_model->updateDiscount($id,$name,$percent);$this->session->set_flashdata('success','Booking discount updated.');redirect('pos/booking_discounts');}
    public function disable($id){if(!$this->Booking_discounts_model->get($id))show_404();$this->Booking_discounts_model->setStatus($id,0);$this->session->set_flashdata('success','Booking discount disabled.');redirect('pos/booking_discounts');}
    public function enable($id){if(!$this->Booking_discounts_model->get($id))show_404();$this->Booking_discounts_model->setStatus($id,1);$this->session->set_flashdata('success','Booking discount enabled.');redirect('pos/booking_discounts');}
    public function delete($id){if(!$this->Booking_discounts_model->get($id))show_404();$this->Booking_discounts_model->delete($id);$this->session->set_flashdata('success','Booking discount deleted.');redirect('pos/booking_discounts');}
}
